 const assertPolicy=(checkInputBinding=false)=>{resources?.assertActive();if(process.env.CATALOG_SELLER_INVENTORY!==sellerEpoch||enforcePower!==(sellerEpoch==='1')||checkInputBinding&&(originalProtected.size!==protectedIds.size||originalExact.size!==exactPreserveMarkets.size||[...protectedIds].some(x=>!originalProtected.has(x))||[...exactPreserveMarkets].some(x=>!originalExact.has(x))))throw Error('canonical_spool_policy_changed');};assertPolicy(true);
