 for await(const input of rows){await execute(async local=>{local();assertPolicy();if(ordinal>=maxRows)throw Error('canonical_spool_fact_cap');const {kind,row}=await prepare(input,{protectedIds,exactPreserveMarkets});const receipt=await spool.append(row);const verifyRow=()=>{if(createHash('sha256').update(JSON.stringify(row)).digest('hex')!==receipt.sha256)throw Error('canonical_spool_fact_binding');};verifyRow();const record={ordinal,kind,id:row.id,receipt};records.push(record);if(resources)recordBytes+=Buffer.byteLength(JSON.stringify(record));
