import {resolveCanonicalResources} from '../production/canonical-resource-limits.mjs';
import { assertBoundedJson } from '../row-spool.mjs';
export function createDedupFacts({ rankedCatalogImageUrls, catalogOfferVisibleRub, reviewedSourceDuplicate, prepareResources, resourceBinding }) {
    const resources=resolveCanonicalResources({prepareResources,resourceBinding}),rowLimit=resources?.limits.maxRows??20000,byteLimit=resources?.limits.maxEncodedBytes??64*1024*1024;
    function clean(value) {
        return String(value ?? "").normalize("NFKC").replace(/\s+/g, " ").trim().toLocaleLowerCase("en-US");
    }
    function finite(value) {
        const number = Number(value);
        return Number.isFinite(number) ? number : "";
    }
    function canonicalImageIdentity(value) {
        const source = String(value || "").trim();
        if (!source)
            return "";
        try {
            const url = new URL(source, "https://catalog.local");
            url.hash = "";
            url.search = "";
            return `${url.hostname.toLowerCase()}${decodeURIComponent(url.pathname).replace(/\/{2,}/g, "/")}`.toLocaleLowerCase("en-US");
        }
        catch {
            return source.replace(/[?#].*$/, "").replace(/\/{2,}/g, "/").toLocaleLowerCase("en-US");
        }
    }
    function coverIdentity(offer) {
        const ranked = rankedCatalogImageUrls(offer)[0];
        if (ranked)
            return canonicalImageIdentity(ranked);
        const first = offer.images?.[0];
        return canonicalImageIdentity(first?.url || first?.objectKey);
    }
    function duplicateKey(offer) {
        const cover = coverIdentity(offer);
        if (!cover)
            return "";
        return [
            clean(offer.market),
            clean(offer.sourceId),
            clean(offer.make),
            clean(offer.model),
            clean(offer.trim),
            finite(offer.year),
            finite(offer.mileageKm),
            finite(offer.engineCc),
            finite(offer.sourcePrice),
            clean(offer.sourceCurrency),
            catalogOfferVisibleRub(offer),
            cover,
        ].join("\u0000");
    }
    function sourcePhotoMatchesOfferId(offer) {
        const sourceOfferId = String(offer.sourceOfferId || "").trim();
        if (!/^\d{6,}$/.test(sourceOfferId))
            return false;
        const evidence = [
            ...rankedCatalogImageUrls(offer).slice(0, 3),
            ...(offer.images || []).slice(0, 3).flatMap((image) => [image.url, image.objectKey]),
            JSON.stringify(offer.operational?.raw || {}).slice(0, 80_000),
        ].join(" ");
        return new RegExp(`(?:^|[^0-9])${sourceOfferId}(?:[_./-]|[^0-9]|$)`).test(evidence);
    }
    function preferredOffer(left, right) {
        const leftMatches = sourcePhotoMatchesOfferId(left);
        const rightMatches = sourcePhotoMatchesOfferId(right);
        if (leftMatches !== rightMatches)
            return rightMatches ? right : left;
        const leftVerified = Number(left.operational?.photoIdentityVerified === true || left.operational?.galleryVerified === true);
        const rightVerified = Number(right.operational?.photoIdentityVerified === true || right.operational?.galleryVerified === true);
        if (leftVerified !== rightVerified)
            return rightVerified > leftVerified ? right : left;
        const leftImages = rankedCatalogImageUrls(left).length;
        const rightImages = rankedCatalogImageUrls(right).length;
        if (leftImages !== rightImages)
            return rightImages > leftImages ? right : left;
        const leftUpdated = Date.parse(String(left.updatedAt || "")) || 0;
        const rightUpdated = Date.parse(String(right.updatedAt || "")) || 0;
        if (leftUpdated !== rightUpdated)
            return rightUpdated > leftUpdated ? right : left;
        return String(right.id).localeCompare(String(left.id), "en") < 0 ? right : left;
    }
    const owned = new WeakSet(), capturedOrdinals = new Set();
    let capturedBytes = 0, capturedCount = 0;
    const ratio = process.env.CATALOG_PUBLIC_MAX_TOTAL_TO_CAR_PRICE_RATIO;
    const assertAuthority = () => { resources?.assertActive(); if (process.env.CATALOG_PUBLIC_MAX_TOTAL_TO_CAR_PRICE_RATIO !== ratio)
        throw Error('dedup_fact_authority'); };
    function seal(value) { const bytes = Buffer.byteLength(JSON.stringify(value)); if (bytes > 16384 || capturedBytes + bytes > byteLimit)
        throw Error('dedup_fact_size'); capturedBytes += bytes; capturedCount++; capturedOrdinals.add(value.ordinal); Object.freeze(value); owned.add(value); return value; }
    function fact(row, ordinal) {
        assertAuthority();
        if (!Number.isSafeInteger(ordinal) || ordinal < 0 || capturedOrdinals.has(ordinal))
            throw Error('dedup_fact_ordinal');
        if (capturedCount >= rowLimit)
            throw Error('dedup_fact_cap');
        assertBoundedJson(row, 1048576);
        const alias = reviewedSourceDuplicate(row);
        if (alias)
            return seal({ ordinal, id: row.id, market: row.market, sourceId: row.sourceId, alias: alias.canonicalId });
        // Domain is immutable JSON rows validated by the row spool; no getters/toJSON.
        return seal({ ordinal, id: row.id, market: row.market, sourceId: row.sourceId, key: duplicateKey(row), cover: coverIdentity(row),
            photoMatches: sourcePhotoMatchesOfferId(row), verified: Number(row.operational?.photoIdentityVerified === true || row.operational?.galleryVerified === true),
            imageCount: rankedCatalogImageUrls(row).length, updated: Date.parse(String(row.updatedAt || '')) || 0 });
    }
    function select(facts, { protectedIds = new Set(), maxFacts = rowLimit } = {}) {
        assertAuthority();
        if (!Array.isArray(facts) || !Number.isSafeInteger(maxFacts) || maxFacts < 0 || facts.length > maxFacts || maxFacts > rowLimit)
            throw Error('dedup_fact_cap');
        let factBytes = 0;
        const ordinals = new Set();
        for (const f of facts) {
            if (!owned.has(f))
                throw Error('dedup_fact_receipt');
            for (const value of Object.values(f))
                if (typeof value === 'string' && value.length > 8192)
                    throw Error('dedup_fact_size');
            const bytes = Buffer.byteLength(JSON.stringify(f));
            factBytes += bytes;
            if (bytes > 16384 || factBytes > byteLimit)
                throw Error('dedup_fact_size');
            if (!Number.isSafeInteger(f.ordinal) || f.ordinal < 0 || ordinals.has(f.ordinal))
                throw Error('dedup_fact_ordinal');
            ordinals.add(f.ordinal);
        }
        const removed = [], eligible = [], groups = new Map(), unique = [];
        for (const f of facts) {
            if (f.alias) {
                removed.push({ keptId: f.alias, removedId: f.id, market: f.market, sourceId: f.sourceId, coverIdentity: 'reviewed:che168-i5-20261001' });
            }
            else
                eligible.push(f);
        }
        for (const f of eligible) {
            if (!f.key)
                unique.push(f);
            else {
                const rows = groups.get(f.key) || [];
                rows.push(f);
                groups.set(f.key, rows);
            }
        }
        const keptIds = new Set(unique.map(f => f.id));
        const preferred = (a, b) => { if (a.photoMatches !== b.photoMatches)
            return b.photoMatches ? b : a; if (a.verified !== b.verified)
            return b.verified > a.verified ? b : a; if (a.imageCount !== b.imageCount)
            return b.imageCount > a.imageCount ? b : a; if (a.updated !== b.updated)
            return b.updated > a.updated ? b : a; return String(b.id).localeCompare(String(a.id), 'en') < 0 ? b : a; };
        for (const rows of groups.values()) {
            let winner = rows[0];
            for (const f of rows.slice(1)) {
                const wp = protectedIds.has(String(winner.id)), fp = protectedIds.has(String(f.id));
                winner = wp !== fp ? (wp ? winner : f) : preferred(winner, f);
            }
            keptIds.add(winner.id);
            for (const f of rows) {
                if (f.id === winner.id)
                    continue;
                removed.push({ keptId: winner.id, removedId: f.id, market: String(f.market || ''), sourceId: String(f.sourceId || ''), coverIdentity: winner.cover });
            }
        }
        return { ordinals: eligible.filter(f => keptIds.has(f.id)).map(f => f.ordinal), removed };
    }
    return { fact, select, assertAuthority, stats: () => ({ capturedCount, capturedBytes }) };
}

